import {
  Group,
  Mesh,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  DoubleSide,
  Shape,
  ExtrudeGeometry,
  PlaneGeometry,
  CircleGeometry,
  Color,
} from 'three/webgpu';
import {
  uv,
  vec3,
  mix,
  distance,
  vec2,
  smoothstep,
  uniform,
  Fn,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors || {};
  const { background, surface, ink, paper, accent, gradientStops } = colors;
  const node = new Group();
  node.name = 'NavigationDock';

  // ---- helper: rounded rectangle shape ----
  const roundedRectShape = (w, h, r) => {
    const shape = new Shape();
    shape.moveTo(-w / 2 + r, -h / 2);
    shape.lineTo(w / 2 - r, -h / 2);
    shape.quadraticCurveTo(w / 2, -h / 2, w / 2, -h / 2 + r);
    shape.lineTo(w / 2, h / 2 - r);
    shape.quadraticCurveTo(w / 2, h / 2, w / 2 - r, h / 2);
    shape.lineTo(-w / 2 + r, h / 2);
    shape.quadraticCurveTo(-w / 2, h / 2, -w / 2, h / 2 - r);
    shape.lineTo(-w / 2, -h / 2 + r);
    shape.quadraticCurveTo(-w / 2, -h / 2, -w / 2 + r, -h / 2);
    return shape;
  };

  // ---- rail (background field) ----
  const railShape = roundedRectShape(3.6, 0.5, 0.1);
  const extrudeSettings = {
    depth: 0.05,
    bevelEnabled: true,
    bevelThickness: 0.02,
    bevelSize: 0.02,
    bevelSegments: 1,
  };
  const railGeo = new ExtrudeGeometry(railShape, extrudeSettings);
  railGeo.translate(0, 0, -0.025);
  const railMat = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
    anisotropy: 0.6,
    side: DoubleSide,
  });
  // Use surface color (near‑black) as solid albedo – no gray gradient
  const surfaceVec = surface
    ? vec3(
        parseInt(surface.slice(1, 3), 16) / 255,
        parseInt(surface.slice(3, 5), 16) / 255,
        parseInt(surface.slice(5, 7), 16) / 255
      )
    : vec3(0.043, 0.043, 0.0627);
  railMat.colorNode = surfaceVec;
  const rail = new Mesh(railGeo, railMat);
  rail.position.z = 0.15;
  node.add(rail);

  // ---- contact shadow ----
  const shadowGeo = new CircleGeometry(2.0, 32);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });
  const shadowOpacity = Fn(() => {
    const center = vec2(0.5, 0.5);
    const dist = distance(uv(), center);
    return smoothstep(0.5, 0.0, dist) * 0.35;
  })();
  shadowMat.opacityNode = shadowOpacity;
  shadowMat.colorNode = vec3(0, 0, 0);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -0.06, -0.05);
  node.add(shadowMesh);

  // ---- entries ----
  const labels = items.map(item => item.text);
  const activeIndex = 0;
  const entryXPositions = labels.map((_, i) => (i - 2) * 0.68);
  const entryGroups = [];

  // ---- underline (kept as subtle accent) ----
  const underlineMat = new MeshStandardNodeMaterial({
    color: new Color(accent || '#ff2a38'),
    emissiveColor: new Color(accent || '#ff2a38'),
    emissiveIntensity: 1.8,
    roughness: 0.3,
    metalness: 0.0,
  });
  const underlineGeo = new PlaneGeometry(0.28, 0.025);
  const underlineMesh = new Mesh(underlineGeo, underlineMat);
  const underlineGroup = new Group();
  underlineGroup.add(underlineMesh);
  underlineGroup.position.x = entryXPositions[activeIndex];
  underlineGroup.position.y = -0.12 - 0.5 * 0.025;
  node.add(underlineGroup);

  // ---- hub mapping ----
  const hubMap = {
    HOME: 'hub-home',
    FEATURES: 'hub-features',
    COLLECTION: 'hub-collection',
    PRICING: 'hub-pricing',
    JOURNAL: 'hub-journal',
  };

  let currentActiveIndex = activeIndex;

  const setActiveEntry = index => {
    if (index === currentActiveIndex) return;
    const prevIdx = currentActiveIndex;
    currentActiveIndex = index;

    // Update text colors
    entryGroups.forEach((g, i) => {
      const textMesh = g.userData.textMesh;
      if (!textMesh) return;
      const targetColor = i === currentActiveIndex ? paper || '#e8ecf2' : '#a6adba';
      textMesh.material.color.set(targetColor);
    });

    // Animate underline
    gsap.to(underlineGroup.position, {
      x: entryXPositions[index],
      duration: 0.26,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      overwrite: 'auto',
      onComplete: () => {
        gsap.set(underlineGroup.scale, { x: 1.04 });
        gsap.to(underlineGroup.scale, {
          x: 1.0,
          duration: 0.2,
          ease: 'power4.out',
          overwrite: 'auto',
        });
      },
    });

    // Toggle pill visibility
    entryGroups.forEach((g, i) => {
      const pill = g.userData.pill;
      if (pill) pill.visible = i === currentActiveIndex;
    });
  };

  // ---- create entries ----
  labels.forEach((label, i) => {
    const group = new Group();
    group.name = `entry-${label}`;
    entryGroups.push(group);
    node.add(group);

    // Text
    const textMesh = ctx.fontAtlas.createText(label, {
      fontSize: 13,
      color: i === activeIndex ? (paper || '#e8ecf2') : '#a6adba',
      align: 'center',
      letterSpacingPx: 0.08 * 13,
    });
    textMesh.userData.isText = true;
    group.add(textMesh);
    group.userData.textMesh = textMesh;

    // Pill background (center pill) – accent color
    const pillShape = roundedRectShape(0.6, 0.34, 0.08);
    const pillGeo = new ExtrudeGeometry(pillShape, {
      depth: 0.02,
      bevelEnabled: false,
    });
    const pillMat = new MeshStandardNodeMaterial({
      color: new Color(accent || '#ff2a38'),
      roughness: 0.55,
      metalness: 0.5,
    });
    const pillMesh = new Mesh(pillGeo, pillMat);
    pillMesh.position.set(0, 0, -0.01);
    pillMesh.visible = i === activeIndex;
    group.add(pillMesh);
    group.userData.pill = pillMesh;

    // Hit area
    const hitGeo = new PlaneGeometry(0.6, 0.34);
    const hitMat = new MeshBasicNodeMaterial({
      transparent: true,
      opacity: 0,
      side: DoubleSide,
    });
    const hitMesh = new Mesh(hitGeo, hitMat);
    hitMesh.position.z = 0.01;
    group.add(hitMesh);

    // Position
    group.position.x = entryXPositions[i];
    group.position.y = -0.06;

    // Interaction handlers
    const handlers = {
      pointerenter: () => {
        if (i !== currentActiveIndex) {
          gsap.to(textMesh.material.color, {
            r: 0.9098,
            g: 0.9255,
            b: 0.949,
            duration: 0.16,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
            overwrite: 'auto',
          });
        }
      },
      pointerleave: () => {
        if (i !== currentActiveIndex) {
          gsap.to(textMesh.material.color, {
            r: 0.651,
            g: 0.678,
            b: 0.729,
            duration: 0.16,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
            overwrite: 'auto',
          });
        }
      },
      pointerdown: () => {
        gsap.to(group.scale, {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
          overwrite: 'auto',
        });
        gsap.to(group.position, {
          z: -0.03,
          duration: 0.12,
          ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
          overwrite: 'auto',
        });
      },
      pointerup: () => {
        gsap.to(group.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.12,
          ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
          overwrite: 'auto',
        });
        gsap.to(group.position, {
          z: 0,
          duration: 0.12,
          ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
          overwrite: 'auto',
        });
        setActiveEntry(i);
        const hubId = hubMap[label];
        if (hubId) ctx.emit('navigate', { to: hubId });
      },
    };
    hitMesh.userData.handlers = handlers;
    group.userData.handlers = handlers;
  });

  // ---- mount animation ----
  node.position.y = 0.4;
  gsap.to(node.position, {
    y: 0,
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
    overwrite: 'auto',
  });

  // ---- cleanup ----
  node.userData.cleanup = () => {
    gsap.killTweensOf(node);
    gsap.killTweensOf(underlineGroup);
    gsap.killTweensOf(underlineGroup.position);
    entryGroups.forEach(g => {
      gsap.killTweensOf(g);
      gsap.killTweensOf(g.position);
      gsap.killTweensOf(g.scale);
      if (g.userData.textMesh) {
        gsap.killTweensOf(g.userData.textMesh.material.color);
        g.userData.textMesh.material.dispose();
      }
      if (g.userData.pill) {
        g.userData.pill.material.dispose();
        g.userData.pill.geometry.dispose();
      }
    });
    railGeo.dispose();
    railMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();
  };

  return node;
}
